// Package sshgrant is `geas ssh`, the human's side of agent SSH access: it
// grants an agent a certificate, signed by an agent CA on a YubiKey, that
// lets it log in as the user agent on the hosts named, for a few hours. Each
// agent has its own key, generated by its first grant, under
// $XDG_STATE_HOME/geas/agents/<name>; every grant signs that key again.
//
// Signing asks for the YubiKey's FIDO2 PIN and a touch, at the human's
// terminal: grant and enroll refuse without one, and inside a session.
package sshgrant

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
	"time"
)

// Tool is geas ssh, with what it takes from its surroundings, which the
// tests replace.
type Tool struct {
	Stdin          io.Reader
	Stdout, Stderr io.Writer
	// Terminal reports whether the human's terminal is on stdin and stderr.
	Terminal func() bool
	Now      func() time.Time
	// SystemCAs is the system's CA list, read before the user's.
	SystemCAs string
}

// New is geas ssh at the process's own terminal.
func New() *Tool {
	return &Tool{
		Stdin:     os.Stdin,
		Stdout:    os.Stdout,
		Stderr:    os.Stderr,
		Terminal:  func() bool { return isTerminal(0) && isTerminal(2) },
		Now:       time.Now,
		SystemCAs: SystemCAs,
	}
}

// Usage is geas ssh's help.
const Usage = `Usage: geas ssh COMMAND

Grants an agent SSH access, as user agent, to the hosts you name, for a few
hours: a certificate signed by an agent CA on your YubiKey, for the agent's
own key.

Commands:
  grant AGENT HOST... [--for DURATION] [--ca YK-NAME]
                    Sign AGENT's certificate for each HOST, for DURATION (default
                    4h, at most 12h; e.g. 30m, 2h), with the enrolled YubiKey
                    plugged in, or the one --ca names. Asks for its FIDO2 PIN
                    and a touch: run it yourself, at your terminal
  show [AGENT]      The certificate's key ID, serial, validity and principals;
                    without AGENT, every agent with a key
  drop AGENT        Delete AGENT's key and certificate
  enroll YK-NAME    Create an agent CA on the one YubiKey plugged in, once per
                    YubiKey, and print its serial, public key and handle path
  list-cas          The agent CAs this machine knows, and which are plugged in
  name [TOOL]       The agent's name, TOOL-<workspace>; without TOOL,
                    $AGENT_SSH_NAME, which a session sets

AGENT is a name as geas ssh name prints it. The CAs are listed in
/etc/agent-grant/cas, then $XDG_CONFIG_HOME/geas/cas, one
"<serial> <yk-name> <handle path>" per line.`

// errUsage is a command line geas ssh does not take.
type errUsage struct{ text string }

func (e errUsage) Error() string { return e.text }

// Run runs geas ssh with its arguments, returning the exit code: 2 for a
// command line it does not take, 1 for any other error.
func (t *Tool) Run(ctx context.Context, args []string) (int, error) {
	err := t.run(ctx, args)
	var usage errUsage
	switch {
	case err == nil:
		return 0, nil
	case errors.As(err, &usage):
		return 2, err
	}
	// The human runs geas ssh: name the file, which main's generic message
	// for file errors would hide.
	var path *os.PathError
	if errors.As(err, &path) {
		err = fmt.Errorf("%s %s: %v", path.Op, path.Path, path.Err)
	}
	return 1, err
}

func (t *Tool) run(ctx context.Context, args []string) error {
	if len(args) == 0 {
		fmt.Fprintln(t.Stderr, Usage)
		return errUsage{"specify a geas ssh command"}
	}
	if args[0] == "-h" || args[0] == "--help" || args[0] == "help" {
		fmt.Fprintln(t.Stdout, Usage)
		return nil
	}
	command, args := args[0], args[1:]
	// The PIN and the touch must come from the human, never from a session
	// whose agent asked for them.
	if (command == "grant" || command == "enroll") && os.Getenv("GEAS_SESSION_DIR") != "" {
		return errors.New("geas ssh " + command + " refuses to run inside a geas session: run it yourself, at your own terminal")
	}
	switch command {
	case "grant":
		duration, ca := defaultFor, ""
		var rest []string
		for i := 0; i < len(args); i++ {
			switch arg := args[i]; {
			case arg == "--for" || arg == "--ca":
				if i+1 == len(args) {
					return errUsage{arg + " needs a value"}
				}
				i++
				if arg == "--for" {
					duration = args[i]
				} else {
					ca = args[i]
				}
			case strings.HasPrefix(arg, "-"):
				return errUsage{"unknown option: " + arg}
			default:
				rest = append(rest, arg)
			}
		}
		if len(rest) == 0 {
			return errUsage{"usage: geas ssh grant AGENT HOST... [--for DURATION] [--ca YK-NAME]"}
		}
		return t.grant(rest[0], rest[1:], duration, ca)
	case "show":
		if len(args) > 1 || hasOption(args) {
			return errUsage{"usage: geas ssh show [AGENT]"}
		}
		if len(args) == 0 {
			return list(t.Stdout, t.Now())
		}
		return show(t.Stdout, Slug(args[0]))
	case "drop":
		if len(args) != 1 || hasOption(args) {
			return errUsage{"usage: geas ssh drop AGENT"}
		}
		return drop(t.Stdout, Slug(args[0]))
	case "enroll":
		if len(args) != 1 || hasOption(args) {
			return errUsage{"usage: geas ssh enroll YK-NAME"}
		}
		return t.enroll(args[0])
	case "list-cas":
		if len(args) != 0 {
			return errUsage{"usage: geas ssh list-cas"}
		}
		return t.listCAs(t.Stdout)
	case "name":
		if len(args) > 1 || hasOption(args) {
			return errUsage{"usage: geas ssh name [TOOL]"}
		}
		tool := ""
		if len(args) == 1 {
			tool = args[0]
		}
		name, err := Name(ctx, tool)
		if err != nil {
			return err
		}
		fmt.Fprintln(t.Stdout, name)
		return nil
	}
	return errUsage{"unknown geas ssh command: " + command}
}

func hasOption(args []string) bool {
	for _, arg := range args {
		if strings.HasPrefix(arg, "-") {
			return true
		}
	}
	return false
}
